/* ==========================================================================
   THEME DEFINITIONS (6 DISTINCT DARK MODE UI VARIATIONS)
   ========================================================================== */
:root {
    /* Default Theme: 1. Cyber Neon (Deep Obsidian + Cyber Indigo & Magenta Glow) */
    --theme-name: "1. Cyber Neon";
    --bg-base: #090c15;
    --bg-surface: #101625;
    --bg-surface-hover: #172033;
    --bg-card: #141c2e;
    --bg-card-hover: #1a253d;
    --bg-input: #0b101c;
    --border-subtle: rgba(99, 102, 241, 0.18);
    --border-glow: rgba(99, 102, 241, 0.5);
    --accent-primary: #6366f1;
    --accent-secondary: #ec4899;
    --accent-tertiary: #06b6d4;
    --accent-glow: rgba(99, 102, 241, 0.4);
    --accent-glow-strong: rgba(99, 102, 241, 0.65);
    --text-title: #f8fafc;
    --text-main: #e2e8f0;
    --text-muted: #94a3b8;
    --text-dim: #64748b;
    --success: #10b981;
    --success-glow: rgba(16, 185, 129, 0.3);
    --warning: #f59e0b;
    --dange

/* ==========================================================================
   FIXED TOP-RIGHT 6-VERSION SWITCHER
   ========================================================================== */
.version-switcher {
    position: fixed;
    top: 16px;
    right: 20px;
    z-index: 1100;
    background: var(--bg-surface);
    border: 1px solid var(--border-glow);
    border-radius: 50px;
    padding: 4px 8px;
    display: flex;
    align-items: center;
    gap: 4px;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.8), 0 0 15px var(--accent-glow);
    backdrop-filter: blur(12px);
}

.switcher-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    padding: 0 8px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.switcher-label::before {
    content: '';
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-primary);
    box-shadow: 0 0 8px var(--accent-primary);

/* ==========================================================================
   SIDEBAR WITH ACCORDION SUB-MENUS
   ========================================================================== */
.sidebar {
    width: 270px;
    background: var(--bg-surface);
    border-right: 1px solid var(--border-subtle);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 100;
    padding: 24px 16px;
    overflow-y: auto;
}

.sidebar-brand {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 8px 24px 8px;
    border-bottom: 1px solid var(--border-subtle);
}

.brand-logo {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 15px var(--accent-glow-strong);
    position: relative;
}

.brand

/* ==========================================================================
   MAIN LAYOUT & HEADER
   ========================================================================== */
.main-wrapper {
    margin-left: 270px;
    flex: 1;
    padding: 32px 36px 60px 36px;
    display: flex;
    flex-direction: column;
    gap: 28px;
    max-width: 1650px;
}

/* Top Header */
.top-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    flex-wrap: wrap;
}

.header-title-area h1 {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 26px;
    font-weight: 800;
    color: var(--text-title);
    letter-spacing: -0.5px;
    display: flex;
    align-items: center;
    gap: 12px;
}

.theme-pill-badge {
    font-size: 11px;
    font-family: var(--font-mono);
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 20px;
    background: var(--bg-surface);
    border: 1px solid var(--border-glow);
    color: var(--accent-primary)

/* ==========================================================================
   DATA TIMEFRAME TABS (WITH SKELETON LOADER TRIGGER)
   ========================================================================== */
.tab-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: var(--bg-surface);
    border: 1px solid var(--border-subtle);
    border-radius: 14px;
    padding: 6px;
    flex-wrap: wrap;
    gap: 12px;
}

.tabs-group {
    display: flex;
    align-items: center;
    gap: 4px;
}

.tab-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 13px;
    font-weight: 600;
    padding: 8px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.tab-btn:hover {
    color: var(--text-title);
    background: var(--bg-surface-hover);
}

.tab-btn.active {
    background: var(--bg-card);
    color: var(--accent-primary);
    border: 1px solid var(--border-subtle);
