/* ==========================================================================
   MODAL SLIDE-OVER POPUP ("+ ADD PROJECT")
   ========================================================================== */
.modal-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(8px);
    z-index: 2000;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

.modal-backdrop.active {
    opacity: 1;
    pointer-events: auto;
}

.slide-over-panel {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    max-width: 480px;
    background: var(--bg-surface);
    border-left: 1px solid var(--border-glow);
    z-index: 2010;
    padding: 32px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    box-shadow: -20px 0 50px rgba(0, 0, 0, 0.9

/* Reflow the original workspace without scaling its content. */
.main-wrapper {
    min-width: 0;
    padding-top: 76px;
}
.widget-card, .kpi-card {
    min-width: 0;
}
.header-controls, .widget-header, .header-title-area h1 {
    flex-wrap: wrap;
}
.version-switcher {
    max-width: calc(100% - 24px);
    flex-wrap: wrap;
}
@media (max-width: 900px) {
    body {
        flex-direction: column;
    }
    .sidebar {
        position: relative;
        width: 100%;
        top: auto;
        bottom: auto;
        border-right: 0;
        padding-top: 76px;
    }
    .main-wrapper {
        margin-left: 0;
        width: 100%;
        padding: 24px;
    }
}
@media (max-width: 600px) {
    .version-switcher {
